// 1. Get the 8 Exercises from your normalization node
const aiExercises = $("edit_exercise_name").all();

// 2. Get the 30 Rows coming directly from the Google Sheet node
const sheetRows = $input.all();

// 3. Map through the 8 items to find matches
return aiExercises.map(exerciseItem => {
  const exercise = exerciseItem.json;

  // Find match in the 30 rows using the 'exercise_name_normalized' column
  const match = sheetRows.find(row => {
    const sheetName = row.json?.exercise_name_normalized;
    const aiName = exercise.exercise_name_normalized;

    return sheetName && aiName && 
           sheetName.toString().toLowerCase().trim() === aiName.toString().toLowerCase().trim();
  });

  return {
    json: {
      // Keep all original workout details (reps, rounds, date)
      ...exercise,
      // If found, pull the real ID from your sheet; otherwise, label it
      exercise_id: match ? match.json.exercise_id : "PENDING",
      //exercise_name_normalized: //match.json.exercise_name_normalized,
      is_new: !match
    }
  };
});

// 1. Reference the 'get_exercise_list' node from the beginning of the workflow
// This node contains the clean state before any 'PENDING' rows were added.
const catalogItems = $("get_exercise_list").all();

// 2. Extract numeric IDs and find the true Maximum
// We use Number() and filter(isFinite) to ensure we don't hit NaN errors
const existingIds = catalogItems
  .map(item => Number(item.json.exercise_id))
  .filter(id => Number.isFinite(id));

const currentMax = existingIds.length > 0 ? Math.max(...existingIds) : 0;

// 3. Process the new exercises needing IDs (from the 'True' path)
const pendingExercises = $input.all();

return pendingExercises.map((item, index) => {
  return {
    json: {
      ...item.json,
      // Increment based on position in the current batch (1-based index)
      exercise_id: currentMax + (index + 1),
      is_new: true           // EXPLICITLY RE-ASSERT THIS HERE
    }
  };
});

// 1. Clean the AI string by removing Markdown backticks and whitespace
let rawOutput = $input.item.json.output || "";
let cleanedOutput = rawOutput.replace(/```json/g, "").replace(/```/g, "").trim();

// 2. Parse the cleaned string
let aiMetadata;
try {
  aiMetadata = JSON.parse(cleanedOutput);
} catch (e) {
  // Fallback if the AI output is completely garbled
  aiMetadata = { exercise_name: "Error Parsing Name" };
}

// 3. Return with the PENDING flag for our batch ID logic
return {
  ...aiMetadata,
  exercise_id: "PENDING"
};

// 1. DECLARE INPUTS
const workoutHistory = $("get_workout_exercise").all();
const workoutTypes = $("get_workout_types").all();
const workoutData = $("split_out_exercise").all();
const mergedItems = $("merge_new_exerciseid").all();

// 2. CALCULATE NEXT WORKOUT ID (Max + 1)
const existingIds = workoutHistory
  .map(item => Number(item.json.workout_id))
  .filter(id => Number.isFinite(id));
const nextWorkoutId = (existingIds.length > 0 ? Math.max(...existingIds) : 0) + 1;

// 3. MAP EVERYTHING TOGETHER
return mergedItems.map((item) => {
  // JOIN: Find original metadata using the validated key 'exercise_name'
  // We use .trim().toLowerCase() to ensure a 100% match success rate
  const match = workoutData.find(d => 
    d.json.exercise_name?.toLowerCase().trim() === item.json.exercise_name_normalized?.toLowerCase().trim()
  );

  const original = match ? match.json : {};

  // LOOKUP: Resolve workout_type_id from your reference table
  const typeMatch = workoutTypes.find(t => 
    t.json.workout_type_name?.toLowerCase().trim() === original.workout_type_name?.toLowerCase().trim()
  );
  const actualTypeId = typeMatch ? typeMatch.json.workout_type_id : null;

  return {
    json: {
      ...item.json,                  // Keep: exercise_id, row_number, is_new, name_normalized
      workout_id: nextWorkoutId,     // Add: The incremented session ID
      workout_date: original.workout_date,
      workout_type_id: actualTypeId, // Resolved from the reference sheet
      workout_rounds: original.rounds,
      workout_repetition_type: original.repetition_type,
      workout_repetition_amount: original.repetition_amount
    }
  };
});

// 1. GATHER INPUTS
const workoutData = $("code_workout_exercise").all();
const workoutTypes = $("get_workout_types").all(); // Reference table with names/IDs

// 2. EXTRACT METRICS
const totalExercises = workoutData.length;
const newExercises = workoutData.filter(item => item.json.is_new === true).length;

// 3. REVERSE LOOKUP: ID -> NAME
const firstRow = workoutData[0]?.json;
const typeMatch = workoutTypes.find(t => 
  Number(t.json.workout_type_id) === Number(firstRow?.workout_type_id)
);
const typeName = typeMatch ? typeMatch.json.workout_type_name : "Unknown Type";
const workoutDate = firstRow?.workout_date || "Today";

// 4. CONSTRUCT THE FINAL LOG
const successMessage = `
✅ **Workout Logged Successfully!**

📅 **Date:** ${workoutDate}
🏋️ **Workout Type:** ${typeName} 
📊 **Total Exercises:** ${totalExercises}
✨ **New Catalog Entries:** ${newExercises}

All records have been updated in your Google Sheet.
`.trim();

return [{
  json: {
    output: successMessage
  }
}];

// This ensures we handle every exercise in the incoming list
return items.map(item => {
  // We extract the current frequency and ID from the incoming stream
  // We use Number() to prevent string concatenation (e.g., "1" + 1 = "11")
  const currentFrequency = Number(item.json.exercise_frequency) || 0;

  return {
