// ── PARSE AGENT INTENT ───────────────────────────────────────────
var agentRaw = $('ai_agent_prompt_process').first().json.output;
var agentOutput = JSON.parse(agentRaw);

var focusRaw = (agentOutput.body_part_focus || 'full body').toLowerCase().trim();
var volumeMode = (agentOutput.volume_logic || 'same').toLowerCase();
var isProgressive = volumeMode === 'progressive';
var workoutSize = parseInt(agentOutput.workout_size) || 5;

// ── CATALOG & HISTORY ────────────────────────────────────────────
var catalog = $('get_exercise_catalog').all();
var history = $('get_recent_workouts').all();

// ── FILTER by body part ──────────────────────────────────────────
var pool = catalog.filter(function(ex) {
  var bp = (ex.json.exercise_body_part_focus || '').toLowerCase();
  if (focusRaw === 'full body') return true;
  return bp.includes(focusRaw) || focusRaw.includes(bp);
});

if (pool.length === 0) pool = catalog;

// ── SORT by frequency ascending (least used first) ───────────────
pool.sort(function(a, b) {
  var fa = Number(a.json.exercise_frequency) || 0;
  var fb = Number(b.json.exercise_frequency) || 0;
  return fa - fb;
});

// ── 80/20 SPLIT ──────────────────────────────────────────────────
var lowCount = Math.max(1, Math.round(workoutSize * 0.2));
var highCount = workoutSize - lowCount;

var lowFreqSize = Math.ceil(pool.length * 0.3);
var highFreqSize = Math.ceil(pool.length * 0.7);
var lowFreqPool = pool.slice(0, lowFreqSize);
var highFreqPool = pool.slice(pool.length - highFreqSize);

function pickRandom(arr, n) {
  var shuffled = arr.slice().sort(function() { return Math.random() - 0.5; });
  return shuffled.slice(0, Math.min(n, shuffled.length));
}

var highPicks = pickRandom(highFreqPool, highCount);
var lowPicks = pickRandom(lowFreqPool, lowCount);
var combined = highPicks.concat(lowPicks);

// ── DEDUPLICATE ──────────────────────────────────────────────────
var seen = {};
var selected = [];
for (var di = 0; di < combined.length; di++) {
  var exNameCheck = (combined[di].json.exercise_name || '').toLowerCase().trim();
  if (!seen[exNameCheck]) {
    seen[exNameCheck] = true;
    selected.push(combined[di]);
  }
}

// Fill gaps caused by deduplication
if (selected.length < workoutSize) {
  var remaining = pool.filter(function(ex) {
    var n = (ex.json.exercise_name || '').toLowerCase().trim();
    return !seen[n];
  });
  var extras = pickRandom(remaining, workoutSize - selected.length);
  for (var ei = 0; ei < extras.length; ei++) {
    seen[(extras[ei].json.exercise_name || '').toLowerCase().trim()] = true;
    selected.push(extras[ei]);
  }
}

// ── MOVEMENT PATTERN ROTATION ────────────────────────────────────
var patternOrder = ['squat', 'hinge', 'push', 'pull', 'rotation', 'carry'];
selected.sort(function(a, b) {
  var pa = patternOrder.indexOf((a.json.exercise_movement_pattern || '').toLowerCase());
  var pb = patternOrder.indexOf((b.json.exercise_movement_pattern || '').toLowerCase());
  return (pa === -1 ? 99 : pa) - (pb === -1 ? 99 : pb);
});

// ── LOOK UP LAST USED REPS/ROUNDS ────────────────────────────────
function getLastEntry(exerciseName) {
  var nameLower = (exerciseName || '').toLowerCase().trim();
  var namePlural = nameLower.endsWith('s') ? nameLower : nameLower + 's';
  var nameSingular = nameLower.endsWith('s') ? nameLower.slice(0, -1) : nameLower;
  var matches = history.filter(function(h) {
    var hName = (h.json.workout_exercise_name || '').toLowerCase().trim();
    return hName === nameLower || hName === namePlural || hName === nameSingular;
  });
  matches.sort(function(a, b) {
    return (b.json.workout_date || '').localeCompare(a.json.workout_date || '');
  });
  return matches.length > 0 ? matches[0].json : null;
}

// ── BUILD OUTPUT ─────────────────────────────────────────────────
var result = selected.map(function(ex) {
  var last = getLastEntry(ex.json.exercise_name);
  var baseReps = last ? (last.workout_repetition_amount || 10) : 10;
  var baseRounds = last ? Number(last.workout_rounds) || 3 : 3;
  var repType = last ? (last.workout_repetition_type || 'reps') : 'reps';

  if (isProgressive) {
    if (repType === 'time') {
      var timeStr = String(baseReps).toLowerCase().trim();
      var timeNum = parseFloat(timeStr);
      var isMin = timeStr.includes('min');
      var isSec = timeStr.includes('sec');
      if (!isNaN(timeNum)) {
        var increased = Math.ceil(timeNum * 1.1);
        if (isMin) {
          baseReps = increased + ' min';
        } else if (isSec) {
          baseReps = increased + ' sec';
        } else {
          baseReps = increased + ' sec';
        }
      }
    } else {
      baseReps = Math.ceil(Number(baseReps) * 1.1);
    }
  }

  var exResult = {};
  exResult.exercise_name = ex.json.exercise_name;
  exResult.body_part = ex.json.exercise_body_part_focus;
  exResult.movement_pattern = ex.json.exercise_movement_pattern;
  exResult.equipment = ex.json.exercise_primary_equipment;
  exResult.repetition_type = repType;
  exResult.repetition_amount = baseReps;
  exResult.rounds = baseRounds;
  exResult.is_new_exercise = (Number(ex.json.exercise_frequency) || 0) === 0;
  exResult.muscles_worked = ex.json.exercise_muscles_worked || '';
  exResult.intensity_type = ex.json.exercise_intensity_type || '';
  return exResult;
});

return [{ json: {
  body_part_focus: focusRaw,
  volume_mode: volumeMode,
  exercises: result,
  original_request_json: JSON.stringify(agentOutput)
}}];

