    sLines.push((s + 1) + '. ' + sx.exercise_name + sTag);
    sLines.push('   ' + sx.rounds + ' rounds x ' + sx.repetition_amount + ' ' + sx.repetition_type);
    sLines.push('   Movement Pattern: ' + (sx.movement_pattern || ''));
