var agentOutput = JSON.parse(agentRaw);
var action = agentOutput.action;
var catalog = $('get_exercise_catalog_modify').all();
var history = $('get_recent_workouts_modify').all();
var currentExercises = [];
try {
  var stagedRaw = $('get_staged_workout').first().json.exercises_json;
  if (stagedRaw && stagedRaw !== 'undefined') {
