function findInCatalog(name) {
  var nameLower = name.toLowerCase().trim();
  var namePlural = nameLower.endsWith('s') ? nameLower : nameLower + 's';
  var nameSingular = nameLower.endsWith('s') ? nameLower.slice(0, -1) : nameLower;

  for (var i = 0; i < catalog.length; i++) {
    var cat = catalog[i].json;
    var catName = (cat.exercise_name || '').toLowerCase().trim();
    var catNorm = (cat.exercise_name_normalized || '').toLowerCase().trim();

    if (catName === nameLower || catNorm === nameLower ||
        catName === namePlural || catName === nameSingular ||
        catNorm === namePlural || catNorm === nameSingular) {
      return cat;
    }
  }
  return null;
}

function findInHistory(name) {
  var nameLower = name.toLowerCase().trim();
  var namePlural = nameLower.endsWith('s') ? nameLower : nameLower + 's';
  var nameSingular = nameLower.endsWith('s') ? nameLower.slice(0, -1) : nameLower;
  var best = null;
  for (var i = 0; i < history.length; i++) {
    var h = history[i].json;
    var hName = (h.workout_exercise_name || '').toLowerCase().trim();
    if (hName === nameLower || hName === namePlural || hName === nameSingular) {
      if (!best || (h.workout_date || '') > (best.workout_date || '')) {
        best = h;
      }
    }
  }
  return best;
}

function buildExercise(catEntry, histEntry) {
  var repType = 'reps';
  if (histEntry && histEntry.workout_repetition_type) {
    repType = histEntry.workout_repetition_type;
  }
  var repAmount = 10;
  if (histEntry && histEntry.workout_repetition_amount) {
    repAmount = histEntry.workout_repetition_amount;
  }
  var rounds = 3;
  if (histEntry && histEntry.workout_rounds) {
    rounds = Number(histEntry.workout_rounds);
  }
  var ex = {};
  ex.exercise_name = catEntry.exercise_name;
  ex.body_part = catEntry.exercise_body_part_focus;
  ex.movement_pattern = catEntry.exercise_movement_pattern;
  ex.equipment = catEntry.exercise_primary_equipment;
  ex.repetition_type = repType;
  ex.repetition_amount = repAmount;
  ex.rounds = rounds;
  ex.is_new_exercise = (Number(catEntry.exercise_frequency) || 0) === 0;
  return ex;
}

function makeResult(exercises) {
  var r = {};
  r.body_part_focus = 'full body';
  r.volume_mode = 'same';
  r.exercises = exercises;
  // Default to clearing any pending suggestion state. Only the
  // suggest_replacements branch below re-populates these.
  r.suggestions_json = '';
  r.target_index = '';
  try {
    var stagedOrig = $('get_staged_workout').first().json.original_request_json;
    if (stagedOrig && stagedOrig !== 'undefined') {
      r.original_request_json = stagedOrig;
    }
  } catch(e) {}
  return r;
}

function applyProgressiveOverload(repType, baseReps) {
  if (repType === 'time') {
    var timeStr = String(baseReps).toLowerCase().trim();
    var timeNum = parseFloat(timeStr);
    var isMin = timeStr.indexOf('min') !== -1;
    var isSec = timeStr.indexOf('sec') !== -1;
    if (!isNaN(timeNum)) {
      var increased = Math.ceil(timeNum * 1.1);
      if (isMin) {
        return increased + ' min';
      } else if (isSec) {
        return increased + ' sec';
      } else {
        return increased + ' sec';
      }
    }
    return baseReps;
  }
  return Math.ceil(Number(baseReps) * 1.1);
}

function getLastEntryByName(exerciseName) {
  var nameLower = (exerciseName || '').toLowerCase().trim();
  var matches = [];
  for (var i = 0; i < history.length; i++) {
    var hName = (history[i].json.workout_exercise_name || '').toLowerCase().trim();
    if (hName === nameLower) {
      matches.push(history[i].json);
    }
  }
  matches.sort(function(a, b) {
    return (b.workout_date || '').localeCompare(a.workout_date || '');
  });
  return matches.length > 0 ? matches[0] : null;
}

function pickRandom(arr, n) {
  var shuffled = arr.slice().sort(function() { return Math.random() - 0.5; });
  return shuffled.slice(0, Math.min(n, shuffled.length));
}

// ── NEW: pick candidate replacements for suggest_replacements ──
function pickReplacementCandidates(targetEx, excludeList, count) {
  var excludeLower = excludeList.map(function(n) { return (n || '').toLowerCase().trim(); });
  var targetPattern = (targetEx.movement_pattern || '').toLowerCase();
  var targetBodyPart = (targetEx.body_part || '').toLowerCase();

  var pool = catalog.filter(function(c) {
    var name = (c.json.exercise_name || '').toLowerCase().trim();
    if (excludeLower.indexOf(name) !== -1) return false;
    var pattern = (c.json.exercise_movement_pattern || '').toLowerCase();
    return pattern === targetPattern;
  });

  if (pool.length < count) {
    pool = catalog.filter(function(c) {
      var name = (c.json.exercise_name || '').toLowerCase().trim();
      if (excludeLower.indexOf(name) !== -1) return false;
      var bp = (c.json.exercise_body_part_focus || '').toLowerCase();
      return bp.indexOf(targetBodyPart) !== -1 || targetBodyPart.indexOf(bp) !== -1;
    });
  }

  if (pool.length < count) {
    pool = catalog.filter(function(c) {
      var name = (c.json.exercise_name || '').toLowerCase().trim();
      return excludeLower.indexOf(name) === -1;
    });
  }

  pool.sort(function(a, b) {
    var fa = Number(a.json.exercise_frequency) || 0;
    var fb = Number(b.json.exercise_frequency) || 0;
    return fa - fb;
  });

  var topSlice = pool.slice(0, Math.max(count * 3, count));
  var picked = pickRandom(topSlice, count);
  return picked.map(function(c) {
    return buildExercise(c.json, findInHistory(c.json.exercise_name));
  });
}

function regenerateWorkout(focusRaw, volumeMode, workoutSize) {
  var isProgressive = volumeMode === 'progressive';

  var pool = catalog.filter(function(c) {
    var bp = (c.json.exercise_body_part_focus || '').toLowerCase();
    if (focusRaw === 'full body') return true;
    return bp.indexOf(focusRaw) !== -1 || focusRaw.indexOf(bp) !== -1;
  });

  if (pool.length === 0) {
    pool = catalog.slice();
  }

  pool.sort(function(a, b) {
    var fa = Number(a.json.exercise_frequency) || 0;
    var fb = Number(b.json.exercise_frequency) || 0;
    return fa - fb;
  });

  var lowCount = Math.max(1, Math.round(workoutSize * 0.2));
  var highCount = workoutSize - lowCount;

  var lowFreqSize = Math.ceil(pool.length * 0.3);
  var highFreqSize = Math.ceil(pool.length * 0.7);
  var lowFreqPool = pool.slice(0, lowFreqSize);
  var highFreqPool = pool.slice(pool.length - highFreqSize);

  var selected = pickRandom(highFreqPool, highCount).concat(pickRandom(lowFreqPool, lowCount));

  var patternOrder = ['squat', 'hinge', 'push', 'pull', 'rotation', 'carry'];
  selected.sort(function(a, b) {
    var pa = patternOrder.indexOf((a.json.exercise_movement_pattern || '').toLowerCase());
    var pb = patternOrder.indexOf((b.json.exercise_movement_pattern || '').toLowerCase());
    return (pa === -1 ? 99 : pa) - (pb === -1 ? 99 : pb);
  });

  var result = selected.map(function(c) {
    var last = getLastEntryByName(c.json.exercise_name);
    var baseReps = last ? (last.workout_repetition_amount || 10) : 10;
    var baseRounds = last ? Number(last.workout_rounds) || 3 : 3;
    var repType = last ? (last.workout_repetition_type || 'reps') : 'reps';

    if (isProgressive) {
      baseReps = applyProgressiveOverload(repType, baseReps);
    }

    return {
      exercise_name: c.json.exercise_name,
      body_part: c.json.exercise_body_part_focus,
      movement_pattern: c.json.exercise_movement_pattern,
      equipment: c.json.exercise_primary_equipment,
      repetition_type: repType,
      repetition_amount: baseReps,
      rounds: baseRounds,
      is_new_exercise: (Number(c.json.exercise_frequency) || 0) === 0
    };
  });

  return result;
}

